package com.prasanth.vitalguard.controller;import com.prasanth.vitalguard.model.VitalReading;import com.prasanth.vitalguard.service.VitalService;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/vitals") @CrossOrigin("*") public class VitalController{private final VitalService service;public VitalController(VitalService service){this.service=service;}@PostMapping public VitalReading create(@RequestBody VitalReading v){return service.create(v);}@GetMapping public List<VitalReading> all(){return service.all();}@GetMapping("/alerts") public List<VitalReading> alerts(){return service.alerts();}}
